package ozl.environment;
import java.util.concurrent.*;import java.util.concurrent.atomic.*;
public final class BuddyAuthorsPrefetchTest {
 static void check(boolean value,String message){if(!value)throw new AssertionError(message);}
 static final class Transport {static final AtomicInteger calls=new AtomicInteger();static volatile CountDownLatch entered,release;static volatile String body;static volatile RuntimeException failure;private static String fetchRemoteBody(){calls.incrementAndGet();entered.countDown();try{release.await();}catch(InterruptedException ex){Thread.currentThread().interrupt();return null;}if(failure!=null)throw failure;return body;}}
 static final class Other {private static String fetchRemoteBody(){return "other";}}
 static void arrange(String value){Transport.entered=new CountDownLatch(1);Transport.release=new CountDownLatch(1);Transport.body=value;Transport.failure=null;}
 public static void main(String[] args)throws Exception{
  arrange("signed-original-body");check(BuddyAuthorsPrefetch.start(Transport.class,"A"),"first early request accepted");check(Transport.entered.await(2,TimeUnit.SECONDS),"request begins before native demand");check(!BuddyAuthorsPrefetch.start(Transport.class,"A"),"no duplicate early request");check(BuddyAuthorsPrefetch.consume(Transport.class,"B")==null,"different configuration cannot consume result");check(BuddyAuthorsPrefetch.consume(Other.class,"A")==null,"different defining class cannot consume result");try(java.net.URLClassLoader foreign=new java.net.URLClassLoader(new java.net.URL[]{BuddyAuthorsPrefetchTest.class.getProtectionDomain().getCodeSource().getLocation()},null)){Class<?> foreignOwner=Class.forName(Transport.class.getName(),false,foreign);check(foreignOwner!=Transport.class&&BuddyAuthorsPrefetch.consume(foreignOwner,"A")==null,"same binary name from another classloader cannot consume result");}Transport.release.countDown();BuddyAuthorsPrefetch.Result success=BuddyAuthorsPrefetch.consume(Transport.class,"A");check(success!=null&&success.failure==null&&"signed-original-body".equals(success.body)&&Transport.calls.get()==1,"same original body adopted exactly once");check(BuddyAuthorsPrefetch.consume(Transport.class,"A")==null,"subsequent native demand remains native");
  arrange(null);BuddyAuthorsPrefetch.start(Transport.class,"A");Transport.release.countDown();BuddyAuthorsPrefetch.Result failed=BuddyAuthorsPrefetch.consume(Transport.class,"A");check(failed!=null&&failed.body==null&&failed.failure==null,"remote IO failure remains null for native signed-cache fallback");
  arrange("ignored");RuntimeException exception=new IllegalStateException("original unchecked failure");Transport.failure=exception;BuddyAuthorsPrefetch.start(Transport.class,"A");Transport.release.countDown();check(BuddyAuthorsPrefetch.consume(Transport.class,"A").failure==exception,"original unchecked exception preserved");
  arrange("completed-success");BuddyAuthorsPrefetch.start(Transport.class,"A");Transport.release.countDown();java.lang.reflect.Field pendingField=BuddyAuthorsPrefetch.class.getDeclaredField("pending");pendingField.setAccessible(true);Object completed=((java.util.Map<?,?>)pendingField.get(null)).get(Transport.class);java.lang.reflect.Field resultField=completed.getClass().getDeclaredField("result");resultField.setAccessible(true);((CompletableFuture<?>)resultField.get(completed)).get(2,TimeUnit.SECONDS);Thread.currentThread().interrupt();try{check(BuddyAuthorsPrefetch.consume(Other.class,"A")==null&&Thread.currentThread().isInterrupted(),"unmatched native fallback leaves preexisting interrupt untouched");BuddyAuthorsPrefetch.Result preInterrupted=BuddyAuthorsPrefetch.consume(Transport.class,"A");check(preInterrupted!=null&&preInterrupted.body==null&&preInterrupted.failure==null&&Thread.currentThread().isInterrupted(),"completed success cannot override pre-interrupted native demand");}finally{Thread.interrupted();}
  arrange("ignored");BuddyAuthorsPrefetch.start(Transport.class,"A");check(Transport.entered.await(2,TimeUnit.SECONDS),"interrupt fixture entered");AtomicBoolean interrupted=new AtomicBoolean();Thread nativeDemand=new Thread(()->{BuddyAuthorsPrefetch.Result result=BuddyAuthorsPrefetch.consume(Transport.class,"A");interrupted.set(result!=null&&result.body==null&&Thread.currentThread().isInterrupted());});nativeDemand.start();Thread.sleep(30);nativeDemand.interrupt();nativeDemand.join(2000);check(!nativeDemand.isAlive()&&interrupted.get(),"native interruption returns null and preserves interrupt status");
  System.out.println("PASS author prefetch early start/single request/raw body/failure/exception/interruption/config and class binding");
 }
}
